# Learn more about .exe install scripts:
# http://fleetdm.com/learn-more-about/exe-install-scripts
#
# 3DxWare 10 is a self-extractor that runs a WiX Burn bundle. The self-extractor
# doesn't pass the bundle's exit code through, so the result is read from the
# Burn log and confirmed against the bundle's Programs and Features entry.
# The installer stops the 3DxWare driver (3DxService.exe) while it runs.

$exeFilePath = "${env:INSTALLER_PATH}"
$displayName = "3Dconnexion 3DxWare 10"
$publisher = "3Dconnexion"
$logFile = Join-Path $env:TEMP "3DxWare10_install_$([guid]::NewGuid().ToString('N')).log"

$paths = @(
  'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
  'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
)

function Get-InstalledBundleVersion {
    $versions = @(Get-ChildItem -Path $paths -ErrorAction SilentlyContinue |
        ForEach-Object { Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue } |
        Where-Object {
            $_.DisplayName -eq $displayName -and $_.Publisher -eq $publisher -and
            ($_.BundleUpgradeCode -or $_.QuietUninstallString)
        } |
        ForEach-Object {
            $v = $null
            if ([version]::TryParse("$($_.DisplayVersion)", [ref]$v)) { $v }
        })
    if ($versions.Count -eq 0) { return $null }
    return ($versions | Sort-Object -Descending | Select-Object -First 1)
}

function Write-LogTail {
    if (Test-Path $logFile) {
        Write-Host "Last lines of $($logFile):"
        Get-Content -Path $logFile -Tail 40 | ForEach-Object { Write-Host $_ }
    }
}

try {
    $targetVersion = $null
    [void][version]::TryParse("$((Get-Item $exeFilePath).VersionInfo.ProductVersion)".Trim(), [ref]$targetVersion)

    $process = Start-Process -FilePath $exeFilePath `
        -ArgumentList "/quiet /norestart /log `"$logFile`"" `
        -PassThru -Wait
    $exitCode = $process.ExitCode
    Write-Host "Self-extractor exit code: $exitCode"

    if (Test-Path $logFile) {
        $burnExit = Select-String -Path $logFile -Pattern 'Exit code: 0x([0-9A-Fa-f]+)' | Select-Object -Last 1
        if ($burnExit) {
            $exitCode = [Convert]::ToInt32($burnExit.Matches[0].Groups[1].Value, 16)
            Write-Host "Bundle exit code: $exitCode"
        }
    }

    # 3010 = success, restart required; 1641 = success, restart initiated.
    if ($exitCode -notin @(0, 1641, 3010)) {
        Write-LogTail
        Exit $exitCode
    }

    $installedVersion = $null
    $sw = [Diagnostics.Stopwatch]::StartNew()
    while ($sw.Elapsed.TotalSeconds -lt 60) {
        $installedVersion = Get-InstalledBundleVersion
        if ($installedVersion -and (-not $targetVersion -or $installedVersion -ge $targetVersion)) { break }
        Start-Sleep -Seconds 2
    }

    if (-not $installedVersion -or ($targetVersion -and $installedVersion -lt $targetVersion)) {
        Write-Host "$displayName $targetVersion isn't registered after install (found: $installedVersion)."
        Write-LogTail
        Exit 1
    }

    Write-Host "$displayName $installedVersion is installed."
    Remove-Item -Path $logFile -Force -ErrorAction SilentlyContinue
    Exit 0

} catch {
    Write-Host "Error: $_"
    Write-LogTail
    Exit 1
}

refs.a1ebfbeb:
# 3DxWare 10 is a WiX Burn bundle; its components register separately
# (3Dconnexion 3DxWinCore, 3DxSoftware, plug-ins). Uninstalling the bundle
# entry removes all of them. The uninstaller stops the 3DxWare driver.

$displayName = "3Dconnexion 3DxWare 10"
$publisher = "3Dconnexion"

$paths = @(
  'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall',
  'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'
)

function Get-BundleKeys {
    @(Get-ChildItem -Path $paths -ErrorAction SilentlyContinue |
        ForEach-Object { Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue } |
        Where-Object { $_.DisplayName -eq $displayName -and $_.Publisher -eq $publisher })
}

try {
    $matchedKeys = Get-BundleKeys
    if ($matchedKeys.Count -eq 0) {
        Write-Host "$displayName isn't installed."
        Exit 0
    }

    # Burn writes BundleUpgradeCode and QuietUninstallString; Windows Installer writes neither.
    $bundle = $matchedKeys | Where-Object { $_.BundleUpgradeCode -or $_.QuietUninstallString } | Select-Object -First 1
    if (-not $bundle) {
        Write-Host "Found $displayName, but not its bundle uninstall entry."
        Exit 1
    }

    $uninstallCommand = $bundle.QuietUninstallString
    $defaultArgs = ""
    if (-not $uninstallCommand) {
        $uninstallCommand = $bundle.UninstallString
        $defaultArgs = "/uninstall /quiet"
    }
    if (-not $uninstallCommand) {
        Write-Host "No uninstall command recorded for $displayName."
        Exit 1
    }

    $exePath = ""
    $existingArgs = ""
    if ($uninstallCommand -match '^\s*"([^"]+)"\s*(.*)$') {
        $exePath = $matches[1]
        $existingArgs = $matches[2].Trim()
    } elseif ($uninstallCommand -match '(?i)^\s*(.+?\.exe)\s*(.*)$') {
        $exePath = $matches[1]
        $existingArgs = $matches[2].Trim()
    } elseif ($uninstallCommand -match '^\s*(\S+)\s*(.*)$') {
        $exePath = $matches[1]
        $existingArgs = $matches[2].Trim()
    } else {
        Throw "Could not parse uninstall command: $uninstallCommand"
    }

    $uninstallArgs = ("$existingArgs $defaultArgs").Trim()
    if ($uninstallArgs -notmatch '(?i)/norestart') {
        $uninstallArgs = "$uninstallArgs /norestart"
    }

    Write-Host "Uninstall command: $exePath"
    Write-Host "Uninstall args: $uninstallArgs"

    $process = Start-Process -FilePath $exePath -ArgumentList $uninstallArgs -PassThru -Wait
    $exitCode = $process.ExitCode
    Write-Host "Uninstall exit code: $exitCode"

    # 3010 = success, restart required; 1641 = success, restart initiated.
    if ($exitCode -notin @(0, 1641, 3010)) {
        Exit $exitCode
    }

    $sw = [Diagnostics.Stopwatch]::StartNew()
    while ($sw.Elapsed.TotalSeconds -lt 60) {
        if ((Get-BundleKeys).Count -eq 0) {
            Write-Host "$displayName was uninstalled."
            Exit 0
        }
        Start-Sleep -Seconds 2
    }

    Write-Host "$displayName is still registered after uninstall."
    Exit 1

} catch {
    Write-Host "Error: $_"
    Exit 1
}
